import { absent } from "./named/index.js";
import { absentMixed } from "./mixed/index.js";
import { absentDefault } from "./defaults/index.js";
import { absentUsed } from "./used/index.js";

export default function style() {
	const fn = () => absentUsed;
	fn.propTypes =
		process.env.NODE_ENV !== "production"
			? { absent, absentMixed, absentDefault }
			: {};
	return fn;
}
